CREATE OR REPLACE FUNCTION public.fn_demander_mediation_admin(p_litige_id UUID, p_message TEXT DEFAULT NULL) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid UUID; v_litige RECORD; v_auteur TEXT; v_date_str TEXT; v_msg TEXT; BEGIN v_uid := auth.uid(); IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF; SELECT * INTO v_litige FROM litiges WHERE id = p_litige_id; IF v_litige.id IS NULL THEN RETURN jsonb_build_object('error', 'Litige introuvable'); END IF; IF v_litige.statut IN ('FERME', 'RESOLU', 'RESOLUE_SOIGNANT', 'RESOLUE_ETABLISSEMENT', 'RESOLUE_ADMIN') THEN RETURN jsonb_build_object('error', 'Ce litige est déjà clôturé'); END IF; IF v_litige.statut = 'EN_MEDIATION' THEN RETURN jsonb_build_object('error', 'La médiation est déjà demandée'); END IF; IF v_uid = v_litige.soignant_id THEN v_auteur := 'Soignant'; ELSIF v_uid = v_litige.etablissement_id OR EXISTS (SELECT 1 FROM user_roles WHERE user_id = v_uid AND etablissement_id = v_litige.etablissement_id) THEN v_auteur := 'Établissement'; ELSE RETURN jsonb_build_object('error', 'Non autorisé'); END IF; v_date_str := TO_CHAR(NOW(), 'DD/MM/YYYY HH24:MI'); v_msg := '[' || v_date_str || '] ' || v_auteur || ' (demande médiation): ' || COALESCE(p_message, 'Demande de médiation administrateur'); IF v_litige.reponse IS NOT NULL AND v_litige.reponse != '' THEN v_msg := v_litige.reponse || E'\n---\n' || v_msg; END IF; UPDATE litiges SET statut = 'EN_MEDIATION', reponse = v_msg WHERE id = p_litige_id; RETURN jsonb_build_object('success', true); END; $$; GRANT EXECUTE ON FUNCTION public.fn_demander_mediation_admin(UUID, TEXT) TO authenticated; GRANT EXECUTE ON FUNCTION public.fn_demander_mediation_admin(UUID, TEXT) TO service_role; GRANT EXECUTE ON FUNCTION public.fn_ouvrir_litige_rate_limited(UUID, TEXT) TO authenticated; GRANT EXECUTE ON FUNCTION public.fn_repondre_litige(UUID, TEXT) TO authenticated; GRANT EXECUTE ON FUNCTION public.fn_cloturer_litige_mutuel(UUID) TO authenticated